        this.v[x] = this.v[y];
        this.pc += 2;
        break;
      case 0x1:
        // OR Vx, Vy
        this.v[x] |= this.v[y];
        this.pc += 2;
        break;
      case 0x2:
        // AND Vx, Vy
        this.v[x] &= this.v[y];
        this.pc += 2;
        break;
      case 0x3:
        // XOR Vx, Vy
        this.v[x] ^= this.v[y];
        this.pc += 2;
        break;
      case 0x4: {
        // ADD Vx, Vy; VF = carry
        const sum = this.v[x] + this.v[y];
        this.v[x] = sum & 0xFF;
        this.v[0xF] = sum > 0xFF ? 1 : 0;
        this.pc += 2;
        break;
      }
      case 0x5: {
        // SUB Vx, Vy; VF = NOT borrow
        const orig = this.v[x];
        this.v[x] = (orig - this.v[y]) & 0xFF;
        this.v[0xF] = orig >= this.v[y] ? 1 : 0;
        this.pc += 2;
        break;
      }
      case 0x6: {
        // SHR Vx; VF = LSB
        this.v[0xF] = this.v[x] & 1;
        this.v[x] >>= 1;
        this.pc += 2;
        break;
      }
      case 0x7: {
        // SUBN Vx, Vy; VF = NOT borrow
        const orig = this.v[y];
        this.v[x] = (orig - this.v[x]) & 0xFF;
        this.v[0xF] = orig >= this.v[x] ? 1 : 0;
        this.pc += 2;
        break;
      }
      case 0xE: {
        // SHL Vx; VF = MSB
        this.v[0xF] = (this.v[x] >> 7) & 1;
        this.v[x] = (this.v[x] << 1) & 0xFF;
        this.pc += 2;
        break;
      }
      default:
        this.pc += 2;
        break;
    }
  }

  executeDraw(opcode, x, y, n) {
    const vx = this.v[x];
    const vy = this.v[y];
    this.v[0xF] = 0;

    for (let row = 0; row < n; row++) {
      const spriteByte = this.memory[this.i + row];
      for (let col = 0; col < 8; col++) {
        if (spriteByte & (0x80 >> col)) {
          const px = (vx + col) % DISPLAY_W;
          const py = (vy + row) % DISPLAY_H;
          const idx = py * DISPLAY_W + px;
          if (this.display[idx]) {
            this.v[0xF] = 1; // Collision
          }
          this.display[idx] ^= 1;
        }
      }
    }
    this.pc += 2;
  }

  executeMisc(opcode, x, n, nn, nnn) {
    switch (n) {
      case 0x07:
        // LD Vx, delay
        this.v[x] = this.delayTimer;
        this.pc += 2;
        break;
      case 0x0A:
        // LD Vx, key (wait for key press)
        // This is handled in the key input section; for non-blocking we just skip
        // In a real emulator this blocks. For our implementation, we'll set Vx to 0
        // and the caller should check. Actually, let's implement it properly:
        // We need to wait until a key is pressed. For simplicity in this emulator,
        // we'll set a flag and handle it differently.
        // For now, just set Vx = 0 (non-blocking)
        this.pendingKeyWait = x;
        this.keyWaitActive = true;
        this.pc += 2;
        break;
      case 0x15:
        // LD delay, Vx
        this.delayTimer = this.v[x];
        this.pc += 2;
        break;
      case 0x18:
        // LD sound, Vx
        this.soundTimer = this.v[x];
        this.pc += 2;
        break;
      case 0x1E:
        // ADD I, Vx
        this.i = (this.i + this.v[x]) & 0x0FFF;
        this.pc += 2;
        break;
      case 0x29:
        // LD F, Vx; I = font sprite for digit Vx
        this.i = this.v[x] * 5 + FONT_START;
        this.pc += 2;
        break;
      case 0x33: {
        // LD B, Vx; BCD
        const val = this.v[x];
        this.memory[this.i] = Math.floor(val / 100);
        this.memory[this.i + 1] = Math.floor((val % 100) / 10);
        this.memory[this.i + 2] = val % 10;
        this.pc += 2;
        break;
      }
      case 0x55:
        // LD [I], Vx (save registers)
        for (let j = 0; j <= x; j++) {
          this.memory[this.i + j] = this.v[j];
        }
        this.pc += 2;
        break;
      case 0x65:
        // LD Vx, [I] (load registers)
        for (let j = 0; j <= x; j++) {
          this.v[j] = this.memory[this.i + j];
        }
        this.pc += 2;
        break;
      default:
        this.pc += 2;
        break;
    }
  }

  updateTimers() {
    if (this.delayTimer > 0) this.delayTimer--;
    if (this.soundTimer > 0) this.soundTimer--;
  }

  decodeOpcode(opcode) {
    if (!opcode) return "NOP";
    const x = (opcode >> 8) & 0x0F;
    const y = (opcode >> 4) & 0x0F;
    const n = opcode & 0x0F;
    const nn = opcode & 0xFF;
    const nnn = opcode & 0x0FFF;
    const hi = opcode & 0xF000;

    switch (hi) {
      case 0x0000:
        if (opcode === 0x00E0) return "CLS";
        if (opcode === 0x00EE) return "RET";
        return `SYS 0x${nnn.toString(16).toUpperCase()}`;
      case 0x1000: return `JP 0x${nnn.toString(16).toUpperCase()}`;
      case 0x2000: return `CALL 0x${nnn.toString(16).toUpperCase()}`;
      case 0x3000: return `SE V${x.toString(16).toUpperCase()}, 0x${nn.toString(16).toUpperCase()}`;
      case 0x4000: return `SNE V${x.toString(16).toUpperCase()}, 0x${nn.toString(16).toUpperCase()}`;
      case 0x5000: return `SE V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
      case 0x6000: return `LD V${x.toString(16).toUpperCase()}, 0x${nn.toString(16).toUpperCase()}`;
      case 0x7000: return `ADD V${x.toString(16).toUpperCase()}, 0x${nn.toString(16).toUpperCase()}`;
      case 0x8000: {
        const opNames = {0:"LD",1:"OR",2:"AND",3:"XOR",4:"ADD",5:"SUB",6:"SHR",7:"SUBN",0xE:"SHL"};
        const name = opNames[n] || "???";
        return `8_${n.toString(16).toUpperCase()}: ${name} V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
      }
      case 0x9000: return `SNE V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}`;
      case 0xA000: return `LD I, 0x${nnn.toString(16).toUpperCase()}`;
      case 0xB000: return `JP V0, 0x${nnn.toString(16).toUpperCase()}`;
      case 0xC000: return `RND V${x.toString(16).toUpperCase()}, 0x${nn.toString(16).toUpperCase()}`;
      case 0xD000: return `DRW V${x.toString(16).toUpperCase()}, V${y.toString(16).toUpperCase()}, ${n}`;
      case 0xE000:
        if (nn === 0x9E) return `SKP V${x.toString(16).toUpperCase()}`;
        if (nn === 0xA1) return `SKNP V${x.toString(16).toUpperCase()}`;
        return `E_${n.toString(16).toUpperCase()}: ???`;
      case 0xF000: {
        const miscNames = {0x07:"LD Vx, DLY",0x0A:"LD Vx, KEY",0x15:"LD DLY, Vx",0x18:"LD SNS, Vx",
          0x1E:"ADD I, Vx",0x29:"LD F, Vx",0x33:"LD B, Vx",0x55:"LD [I], Vx",0x65:"LD Vx, [I]"};
        const name = miscNames[n] || "???";
        return `F_${n.toString(16).toUpperCase()}: ${name}`;
      }
      default: return `Unknown: 0x${opcode.toString(16).toUpperCase().padStart(4, '0')}`;
    }
  }
}

// Helper for BCD instruction
function v0_val() { return chip8.v[0]; }

// ============================================================
// UI Setup
// ============================================================
const canvas = document.getElementById('display');
const ctx = canvas.getContext('2d');
ctx.imageSmoothingEnabled = false;

const chip8 = new Chip8();

// Scale canvas for display
function resizeCanvas() {
  const maxW = Math.min(window.innerWidth * 0.5, 640);
  const scale = Math.floor(maxW / DISPLAY_W);
  canvas.style.width = (DISPLAY_W * scale) + 'px';
  canvas.style.height = (DISPLAY_H * scale) + 'px';
}
resizeCanvas();
window.addEventListener('resize', resizeCanvas);

// Draw display
function drawDisplay() {
  const imageData = ctx.createImageData(DISPLAY_W, DISPLAY_H);
  const data = imageData.data;
  for (let i = 0; i < chip8.display.length; i++) {
    const idx = i * 4;
    if (chip8.display[i]) {
      data[idx] = 0;     // R
      data[idx + 1] = 212;  // G
      data[idx + 2] = 255;  // B
      data[idx + 3] = 255;  // A
    } else {
      data[idx] = 0;
      data[idx + 1] = 0;
      data[idx + 2] = 0;
      data[idx + 3] = 255;
    }
  }
  ctx.putImageData(imageData, 0, 0);
}

// Key mapping: CHIP-8 keypad 0-F to keyboard keys
const KEY_MAP = {
  '1': 0x1, '2': 0x2, '3': 0x3, '4': 0x0C,  // 1, 2, 3, D
  'q': 0x4, 'w': 0x5, 'e': 0x6, 'r': 0x0D,  // Q, W, E, R -> 4, 5, 6, D
  'a': 0x7, 's': 0x8, 'd': 0x9, 'f': 0x0E,  // A, S, D, F -> 7, 8, 9, E
  'z': 0xA, 'x': 0x0, 'c': 0xB, 'v': 0x0F,  // Z, X, C, V -> A, 0, B, F
};

// Alternative common mapping
const KEY_MAP_ALT = {
  '1': 1, '2': 2, '3': 3, '4': 0xC,
  'q': 4, 'w': 5, 'e': 6, 'r': 0xD,
  'a': 7, 's': 8, 'd': 9, 'f': 0xE,
  'z': 0xA, 'x': 0, 'c': 0xB, 'v': 0xF,
};

// Keypad labels and keyboard mappings
const KEYPAD_KEYS = [
  { label: '1', key: '1', val: 1 },
  { label: '2', key: '2', val: 2 },
  { label: '3', key: '3', val: 3 },
  { label: '4', key: '4', val: 0xC },
  { label: 'Q', key: 'q', val: 4 },
  { label: 'W', key: 'w', val: 5 },
  { label: 'E', key: 'e', val: 6 },
  { label: 'R', key: 'r', val: 0xD },
  { label: 'A', key: 'a', val: 7 },
  { label: 'S', key: 's', val: 8 },
  { label: 'D', key: 'd', val: 9 },
  { label: 'F', key: 'f', val: 0xE },
  { label: 'Z', key: 'z', val: 0xA },
  { label: 'X', key: 'x', val: 0 },
  { label: 'C', key: 'c', val: 0xB },
  { label: 'V', key: 'v', val: 0xF },
];

// Build keypad UI
const keypadEl = document.getElementById('keypad');
KEYPAD_KEYS.forEach(k => {
  const el = document.createElement('div');
  el.className = 'key';
  el.dataset.key = k.key;
  el.dataset.val = k.val;
  el.innerHTML = `${k.label}<span class="sub">${k.val.toString(16).toUpperCase()}</span>`;
  keypadEl.appendChild(el);
});

function handleKeyDown(e) {
  const key = e.key.toLowerCase();
  // Check our key mapping
  let chip8Key = null;
  for (const k of KEYPAD_KEYS) {
    if (k.key === key) { chip8Key = k.val; break; }
  }
  if (chip8Key !== null) {
    chip8.keys[chip8Key] = 1;
    const keyEl = keypadEl.querySelector(`[data-key="${key}"]`);
    if (keyEl) keyEl.classList.add('pressed');
    e.preventDefault();
  }

  // Global hotkeys
  if (key === ' ') {
    toggleRun();
    e.preventDefault();
  }
  if (key === 'r' && e.ctrlKey) {
    resetEmulator();
    e.preventDefault();
  }
  if (key === 'z' && e.ctrlKey) {
    stepOnce();
    e.preventDefault();
  }
}

function handleKeyUp(e) {
  const key = e.key.toLowerCase();
  let chip8Key = null;
  for (const k of KEYPAD_KEYS) {
    if (k.key === key) { chip8Key = k.val; break; }
  }
  if (chip8Key !== null) {
    chip8.keys[chip8Key] = 0;
    const keyEl = keypadEl.querySelector(`[data-key="${key}"]`);
    if (keyEl) keyEl.classList.remove('pressed');
    e.preventDefault();
  }
}

// Mouse/touch on keypad
keypadEl.addEventListener('mousedown', (e) => {
  const el = e.target.closest('.key');
  if (!el) return;
  const val = parseInt(el.dataset.val);
  chip8.keys[val] = 1;
  el.classList.add('pressed');
  e.preventDefault();
});
keypadEl.addEventListener('mouseup', (e) => {
  const el = e.target.closest('.key');
  if (!el) return;
  const val = parseInt(el.dataset.val);
  chip8.keys[val] = 0;
  el.classList.remove('pressed');
  e.preventDefault();
});
keypadEl.addEventListener('mouseleave', () => {
  chip8.keys.fill(0);
  document.querySelectorAll('.key.pressed').forEach(el => el.classList.remove('pressed'));
});

document.addEventListener('keydown', handleKeyDown);
document.addEventListener('keyup', handleKeyUp);

// ============================================================
// Controls
// ============================================================
const btnRun = document.getElementById('btn-run');
const btnPause = document.getElementById('btn-pause');
const btnStep = document.getElementById('btn-step');
const btnReset = document.getElementById('btn-reset');
const btnDemo = document.getElementById('btn-demo');
const sliderSpeed = document.getElementById('slider-speed');
const speedVal = document.getElementById('speed-val');
const statusText = document.getElementById('status-text');
const fileRom = document.getElementById('file-rom');

let animationId = null;

function toggleRun() {
  if (chip8.running) {
    pause();
  } else {
    run();
  }
}

function run() {
  chip8.running = true;
  btnRun.classList.add('active');
  btnPause.classList.remove('active');
  statusText.textContent = 'Running';
  statusText.style.color = '#00d4ff';
  gameLoop();
}

function pause() {
  chip8.running = false;
  btnPause.classList.add('active');
  btnRun.classList.remove('active');
  statusText.textContent = 'Paused';
  statusText.style.color = '#f0c040';
  if (animationId) {
    cancelAnimationFrame(animationId);
    animationId = null;
  }
}

function stepOnce() {
  pause();
  chip8.execute();
  chip8.updateTimers();
  drawDisplay();
  updateDebugger();
  statusText.textContent = 'Stepped';
  statusText.style.color = '#888';
}

function resetEmulator() {
  pause();
  chip8.reset();
  drawDisplay();
  updateDebugger();
  statusText.textContent = 'Ready';
  statusText.style.color = '#888';
}

btnRun.addEventListener('click', run);
btnPause.addEventListener('click', pause);
btnStep.addEventListener('click', stepOnce);
btnReset.addEventListener('click', resetEmulator);
btnDemo.addEventListener('click', () => {
  chip8.loadROM(DEMO);
  resetEmulator();
  statusText.textContent = 'Demo loaded';
  statusText.style.color = '#888';
});

sliderSpeed.addEventListener('input', () => {
  chip8.instructionsPerFrame = parseInt(sliderSpeed.value);
  speedVal.textContent = sliderSpeed.value;
});

// ROM file loading
fileRom.addEventListener('change', (e) => {
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = (ev) => {
    const bytes = new Uint8Array(ev.target.result);
    chip8.loadROM(bytes);
    resetEmulator();
    statusText.textContent = `Loaded: ${file.name}`;
    statusText.style.color = '#00d4ff';
  };
  reader.readAsArrayBuffer(file);
});

// ============================================================
// Game Loop
// ============================================================
function gameLoop() {
  if (!chip8.running) return;

  for (let i = 0; i < chip8.instructionsPerFrame; i++) {
    chip8.execute();
  }
  chip8.updateTimers();
  drawDisplay();
  updateDebugger();

  animationId = requestAnimationFrame(gameLoop);
}

// ============================================================
// Debugger
// ============================================================
function updateDebugger() {
  const el = document.getElementById('debug-content');
  const pc = chip8.pc;
  const opcode = (chip8.memory[pc] << 8) | chip8.memory[pc + 1];
  const decoded = chip8.decodeOpcode(opcode);

  let html = '<table>';

  // Current instruction
  html += '<tr><th colspan="2">Current Instruction</th></tr>';
  html += `<tr><td>Address</td><td class="val">0x${pc.toString(16).toUpperCase().padStart(4, '0')}</td></tr>`;
  html += `<tr><td>Opcode</td><td class="val">0x${opcode.toString(16).toUpperCase().padStart(4, '0')}</td></tr>`;
  html += `<tr><td>Decoded</td><td class="val">${decoded}</td></tr>`;

  // Registers
  html += '<tr><th colspan="2" style="margin-top:8px;">Registers</th></tr>';
  for (let i = 0; i < 16; i++) {
    const isHighlighted = (i === 0xF && chip8.v[0xF] === 1);
    const cls = isHighlighted ? ' class="highlight"' : '';
    html += `<tr${cls}><td>V${i.toString(16).toUpperCase()}</td><td class="val">${chip8.v[i].toString(16).toUpperCase().padStart(2, '0')} (${chip8.v[i]})</td></tr>`;
  }

  // Special registers
  html += `<tr><th>I</th><td class="val">0x${chip8.i.toString(16).toUpperCase().padStart(4, '0')}</td></tr>`;
  html += `<tr><th>PC</th><td class="val">0x${pc.toString(16).toUpperCase().padStart(4, '0')}</td></tr>`;
  html += `<tr><th>Stack Ptr</th><td class="val">${chip8.stackPtr}</td></tr>`;
  html += `<tr><th>Delay Timer</th><td class="val">${chip8.delayTimer}</td></tr>`;
  html += `<tr><th>Sound Timer</th><td class="val">${chip8.soundTimer}</td></tr>`;

  // Stack
  html += '<tr><th colspan="2" style="margin-top:8px;">Stack</th></tr>';
  for (let i = 0; i < STACK_SIZE; i++) {
    if (i < chip8.stackPtr) {
      html += `<tr class="highlight"><td>[${i}]</td><td class="val">0x${chip8.stack[i].toString(16).toUpperCase().padStart(4, '0')}</td></tr>`;
    } else {
      html += `<tr><td>[${i}]</td><td class="val">-</td></tr>`;
    }
  }

  // Key states
  html += '<tr><th colspan="2" style="margin-top:8px;">Keys</th></tr>';
  let keysHtml = '';
  for (let i = 0; i < 16; i++) {
    keysHtml += chip8.keys[i] ? `<span style="color:#00d4ff;">${i.toString(16).toUpperCase()}</span>` : i.toString(16).toUpperCase();
  }
  html += `<tr><td>State</td><td class="val">${keysHtml}</td></tr>`;

  html += '</table>';
  el.innerHTML = html;
}

// Initial draw
drawDisplay();
updateDebugger();
statusText.textContent = 'Ready — click "Load Demo ROM" or load a .chip8 file';
</script>
</body>
</html>
