<script>
// ============================================================
// CHIP-8 Emulator
// ============================================================
const MEM_SIZE = 4096;
const DISPLAY_W = 64;
const DISPLAY_H = 32;
const FONT_START = 0x050;
const PROGRAM_START = 0x200;
const STACK_SIZE = 16;
const TIMER_FREQ = 60; // Hz

// Standard CHIP-8 font set (5 bytes per digit, 0-F)
const FONT_SET = [
  0xF0, 0x90, 0x90, 0x90, 0xF0, // 0
  0x20, 0x60, 0x20, 0x20, 0x70, // 1
  0xF0, 0x10, 0xF0, 0x80, 0xF0, // 2
  0xF0, 0x10, 0xF0, 0x10, 0xF0, // 3
  0x90, 0x90, 0xF0, 0x10, 0x10, // 4
  0xF0, 0x80, 0xF0, 0x10, 0xF0, // 5
  0xF0, 0x80, 0xF0, 0x90, 0xF0, // 6
  0xF0, 0x10, 0x20, 0x40, 0x40, // 7
  0xF0, 0x90, 0xF0, 0x90, 0xF0, // 8
  0xF0, 0x90, 0xF0, 0x10, 0xF0, // 9
  0xF0, 0x90, 0xF0, 0x90, 0x90, // A
  0xE0, 0x90, 0xE0, 0x90, 0xE0, // B
  0xF0, 0x80, 0x80, 0x80, 0xF0, // C
  0xE0, 0x90, 0x90, 0x90, 0xE0, // D
  0xF0, 0x80, 0xF0, 0x80, 0xF0, // E
  0xF0, 0x80, 0xF0, 0x80, 0x80  // F
];

// Demo ROM: a simple game that draws a sprite and moves it with arrow keys
// Program:
//   V0 = 0x40 (x position), V1 = 0x20 (y position)
//   Load sprite from 0x200 (custom sprite data)
//   Draw sprite, read keys, update position, loop
const DEMO_ROM = [
  // 0x200: main loop
  0x60, 0x40,          // LD V0, 0x40  ; x = 64
  0x61, 0x20,          // LD V1, 0x20  ; y = 32
  0x62, 0x08,          // LD V2, 0x08  ; sprite width
